firmware:
const int UP = 4;
const int DOWN = 5;
int lastUp = HIGH, lastDown = HIGH;
int count = 0;

bool pressed(int pin, int &last) {
  int now = digitalRead(pin);
  bool edge = false;
  if (last == HIGH && now == LOW) {
    delay(30);
    if (digitalRead(pin) == LOW) edge = true;
  }
  last = now;
  return edge;
}

void setup() {
  Serial.begin(115200);
  pinMode(UP, INPUT_PULLUP);
  pinMode(DOWN, INPUT_PULLUP);
}

void loop() {
  bool changed = false;
  if (pressed(UP, lastUp)) { count++; changed = true; }
  if (pressed(DOWN, lastDown)) { count--; changed = true; }
  if (changed) {
    Serial.print("COUNT=");
    Serial.println(count);
  }
  delay(5);
}
